import json
import csv
import os
import re

def parse_wkt_point(coord_str):
    """Parse a WKT POINT string like 'POINT(lon lat)' - note: lon first, then lat."""
    match = re.match(r'POINT\s*\(\s*([\d.\-]+)\s+([\d.\-]+)\s*\)', coord_str, re.IGNORECASE)
    if match:
        lon = float(match.group(1))
        lat = float(match.group(2))
        return lat, lon
    return None, None

