            lon = None
            if 'claims' in entity:
                claims = entity['claims']
                if 'P625' in claims:
                    for claim in claims['P625']:
                        if 'mainsnak' in claim:
                            mainsnak = claim['mainsnak']
                            if 'datavalue' in mainsnak:
                                dv = mainsnak['datavalue']
                                if 'value' in dv:
                                    val = dv['value']
                                    if isinstance(val, str):
                                        # WKT Point
                                        lat, lon = parse_wkt_point(val)
                                    elif isinstance(val, dict):
                                        # Direct lat/lon fields
                                        lat = val.get('latitude')
                                        lon = val.get('longitude')
                        if lat is not None and lon is not None:
                            break

            # Validate
